-- ===========================================================================
-- INF2003 G61 - MedSafety database: FULL SETUP for PostgreSQL 12+ (pgAdmin, DBeaver, psql, ...)
-- ===========================================================================
-- Builds all 15 tables of our ER diagram with data, in one script:
--   Drug reference: Drug, ActiveIngredients, Contains, SideEffects, HasSideEffects,
--                   DrugtoDrugInteraction
--   Clinical:       Patient, Doctor, Pharmacist, Disease, Diagnosis, PrescriptionTemplate,
--                   Prescription, IsAllergicTo, ToAddress
-- WARNING: drops and rebuilds these tables (and the older tables, including IngredientIndication, from previous versions
-- of our scripts). Anything you added by hand is lost.
--
-- HOW TO RUN: create an empty database (e.g. medsafety), connect to it, open this file and run the
-- whole script. The final result is a CHECK table: every row should say PASS.
-- (check_setup_postgres.sql runs the same check again on its own.)
-- Table and column names are unquoted, so PostgreSQL stores them in lowercase
-- (Patient -> patient). Write queries without double quotes and they work as written.
--
-- Differences from the ER diagram (agreed design):
--   * HasSideEffects and DrugtoDrugInteraction use IngredientID instead of DrugID, so one row
--     covers every drug containing that ingredient. Look them up through Contains.
--   * DrugtoDrugInteraction keeps Direction, LabelSaysAvoid and ExampleSentence (alert text);
--     its key is (IngredientID_A, IngredientID_B, Symptom) because a pair can have several symptoms.
--   * PrescriptionTemplate has an extra dosage_form column.
--   * Disease and ToAddress were filled in using the Kaggle / Hugging Face indication data.
--
-- All patients, NRICs, phone numbers, doctors and hospitals are made up. Clinical dates are
-- relative to the day you run this, so active medications stay active: re-run before a demo.
-- ===========================================================================

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

DROP TABLE IF EXISTS ToAddress CASCADE;
DROP TABLE IF EXISTS IsAllergicTo CASCADE;
DROP TABLE IF EXISTS Prescription CASCADE;
DROP TABLE IF EXISTS PrescriptionTemplate CASCADE;
DROP TABLE IF EXISTS Diagnosis CASCADE;
DROP TABLE IF EXISTS Disease CASCADE;
DROP TABLE IF EXISTS Doctor CASCADE;
DROP TABLE IF EXISTS Pharmacist CASCADE;
DROP TABLE IF EXISTS Patient CASCADE;
DROP TABLE IF EXISTS IngredientIndication CASCADE;
DROP TABLE IF EXISTS DrugtoDrugInteraction CASCADE;
DROP TABLE IF EXISTS HasSideEffects CASCADE;
DROP TABLE IF EXISTS SideEffects CASCADE;
DROP TABLE IF EXISTS Contains CASCADE;
DROP TABLE IF EXISTS ActiveIngredients CASCADE;
DROP TABLE IF EXISTS Drug CASCADE;
DROP TABLE IF EXISTS prescription_review CASCADE;
DROP TABLE IF EXISTS app_user CASCADE;
DROP TABLE IF EXISTS allergy CASCADE;
DROP TABLE IF EXISTS prescription_template CASCADE;
DROP TABLE IF EXISTS has_side_effect CASCADE;
DROP TABLE IF EXISTS side_effect CASCADE;
DROP TABLE IF EXISTS ingredient_indication CASCADE;
DROP TABLE IF EXISTS drug_interaction CASCADE;
DROP TABLE IF EXISTS drug_ingredient CASCADE;
DROP TABLE IF EXISTS drug CASCADE;
DROP TABLE IF EXISTS active_ingredient CASCADE;

-- ===========================================================================
-- PART 1: Drug reference tables (ER diagram)
-- One Drug row per GENERIC drug (distinct ingredient combination); strength, route and
-- dosage form live in PrescriptionTemplate. Side effects and interactions are stored per
-- INGREDIENT, so one row covers every drug containing it (look them up through Contains).
-- ===========================================================================
CREATE TABLE Drug (
    DrugID      INT PRIMARY KEY,
    GenericName VARCHAR(255) NOT NULL UNIQUE           -- e.g. METFORMIN HYDROCHLORIDE
);

CREATE TABLE ActiveIngredients (
    IngredientID   INT PRIMARY KEY,
    IngredientName VARCHAR(255) NOT NULL UNIQUE        -- base moiety, e.g. METFORMIN
);

CREATE TABLE Contains (
    DrugID       INT NOT NULL,
    IngredientID INT NOT NULL,
    PRIMARY KEY (DrugID, IngredientID),
    FOREIGN KEY (DrugID)       REFERENCES Drug(DrugID),
    FOREIGN KEY (IngredientID) REFERENCES ActiveIngredients(IngredientID)
);
CREATE INDEX ix_contains_ingredient ON Contains (IngredientID);

CREATE TABLE SideEffects (
    EffectID   INT PRIMARY KEY,
    EffectName VARCHAR(255) NOT NULL UNIQUE
);

CREATE TABLE HasSideEffects (
    IngredientID INT NOT NULL,
    EffectID     INT NOT NULL,
    PRIMARY KEY (IngredientID, EffectID),
    FOREIGN KEY (IngredientID) REFERENCES ActiveIngredients(IngredientID),
    FOREIGN KEY (EffectID)     REFERENCES SideEffects(EffectID)
);

-- Each pair is stored once, smaller IngredientID first. A pair can have several Symptoms.
CREATE TABLE DrugtoDrugInteraction (
    IngredientID_A  INT NOT NULL,
    IngredientID_B  INT NOT NULL,
    Symptom         VARCHAR(255) NOT NULL,              -- bleeding_risk, qt_prolongation, ...
    Direction       VARCHAR(12) NOT NULL,               -- increase / decrease / unspecified
    LabelSaysAvoid  BOOLEAN NOT NULL,                   -- label advises avoiding the combination
    ExampleSentence TEXT,                               -- label sentence to show in the alert
    PRIMARY KEY (IngredientID_A, IngredientID_B, Symptom),
    CONSTRAINT ck_pair_order CHECK (IngredientID_A < IngredientID_B),
    CONSTRAINT ck_direction  CHECK (Direction IN ('increase','decrease','unspecified')),
    FOREIGN KEY (IngredientID_A) REFERENCES ActiveIngredients(IngredientID),
    FOREIGN KEY (IngredientID_B) REFERENCES ActiveIngredients(IngredientID)
);
CREATE INDEX ix_ddi_b ON DrugtoDrugInteraction (IngredientID_B);   -- lookups from either side


-- ===========================================================================
-- PART 2: Clinical tables (ER diagram)
-- ===========================================================================
CREATE TABLE Patient (
    NRIC        VARCHAR(9)   PRIMARY KEY,
    Name        VARCHAR(100) NOT NULL,
    DOB         DATE         NOT NULL,
    Sex         CHAR(1),
    PhoneNumber VARCHAR(20)
);

CREATE TABLE Doctor (
    DoctorID INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    Name     VARCHAR(100) NOT NULL,
    Hospital VARCHAR(150)
);

CREATE TABLE Pharmacist (
    PharmacistID INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    Name         VARCHAR(100) NOT NULL
);

CREATE TABLE Disease (
    DiseaseID INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    Name      VARCHAR(150) NOT NULL UNIQUE
);

CREATE TABLE Diagnosis (
    DiagnosisID     INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    NRIC            VARCHAR(9) NOT NULL,
    DoctorID        INT NOT NULL,
    DiseaseID       INT NOT NULL,
    DateOfDiagnosis DATE NOT NULL,
    FOREIGN KEY (NRIC)      REFERENCES Patient(NRIC),
    FOREIGN KEY (DoctorID)  REFERENCES Doctor(DoctorID),
    FOREIGN KEY (DiseaseID) REFERENCES Disease(DiseaseID)
);
CREATE INDEX ix_diagnosis_nric ON Diagnosis (NRIC);

CREATE TABLE PrescriptionTemplate (
    PrescriptionTemplateID INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    DrugID      INT NOT NULL,
    dose_amount DECIMAL(10,2),
    dose_unit   VARCHAR(20),
    frequency   VARCHAR(50),
    route       VARCHAR(50),
    dosage_form VARCHAR(80),                            -- TABLET, CAPSULE, AEROSOL, METERED, ...
    FOREIGN KEY (DrugID) REFERENCES Drug(DrugID)
);

-- A medication is ACTIVE when ReviewStatus = 'Approved' and today is between
-- PrescriptionStart and PrescriptionEnd (NULL end = ongoing / as needed).
CREATE TABLE Prescription (
    PrescriptionID         INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    DiagnosisID            INT NOT NULL,
    PrescriptionTemplateID INT NOT NULL,
    PrescriptionStart      DATE NOT NULL,
    PrescriptionEnd        DATE,
    PharmacistID           INT,
    ReviewStatus           VARCHAR(20) NOT NULL,        -- Pending / Approved / Rejected
    ReviewedAt             TIMESTAMP,
    ReviewNotes            VARCHAR(255),
    CONSTRAINT ck_review_status CHECK (ReviewStatus IN ('Pending','Approved','Rejected')),
    CONSTRAINT ck_rx_dates CHECK (PrescriptionEnd IS NULL OR PrescriptionEnd >= PrescriptionStart),
    FOREIGN KEY (DiagnosisID)            REFERENCES Diagnosis(DiagnosisID),
    FOREIGN KEY (PrescriptionTemplateID) REFERENCES PrescriptionTemplate(PrescriptionTemplateID),
    FOREIGN KEY (PharmacistID)           REFERENCES Pharmacist(PharmacistID)
);
CREATE INDEX ix_prescription_diagnosis ON Prescription (DiagnosisID);

CREATE TABLE IsAllergicTo (
    NRIC         VARCHAR(9) NOT NULL,
    IngredientID INT NOT NULL,
    Date         DATE,
    Severity     VARCHAR(20),                           -- Mild / Moderate / Severe
    Reactions    VARCHAR(255),
    PRIMARY KEY (NRIC, IngredientID),
    FOREIGN KEY (NRIC)         REFERENCES Patient(NRIC),
    FOREIGN KEY (IngredientID) REFERENCES ActiveIngredients(IngredientID)
);

CREATE TABLE ToAddress (
    DrugID    INT NOT NULL,
    DiseaseID INT NOT NULL,
    PRIMARY KEY (DrugID, DiseaseID),
    FOREIGN KEY (DrugID)    REFERENCES Drug(DrugID),
    FOREIGN KEY (DiseaseID) REFERENCES Disease(DiseaseID)
);

-- ===========================================================================
-- Data
-- ===========================================================================
-- Drug: 2202 rows

-- ActiveIngredients: 2008 rows

-- Contains: 2697 rows

-- SideEffects: 202 rows

-- HasSideEffects: 941 rows

-- DrugtoDrugInteraction: 6684 rows

-- Patient: 50 rows

-- Doctor: 8 rows

-- Pharmacist: 5 rows

-- Disease: 73 rows

-- Diagnosis: 120 rows

-- PrescriptionTemplate: 38 rows

-- Prescription: 182 rows

-- IsAllergicTo: 8 rows

-- ToAddress: 481 rows

-- IDs were inserted explicitly: move each ID counter past the highest ID so new rows get fresh IDs.
SELECT setval(pg_get_serial_sequence('doctor', 'doctorid'), (SELECT MAX(DoctorID) FROM Doctor)) AS doctor_next,
       setval(pg_get_serial_sequence('pharmacist', 'pharmacistid'), (SELECT MAX(PharmacistID) FROM Pharmacist)) AS pharmacist_next,
       setval(pg_get_serial_sequence('disease', 'diseaseid'), (SELECT MAX(DiseaseID) FROM Disease)) AS disease_next,
       setval(pg_get_serial_sequence('diagnosis', 'diagnosisid'), (SELECT MAX(DiagnosisID) FROM Diagnosis)) AS diagnosis_next,
       setval(pg_get_serial_sequence('prescriptiontemplate', 'prescriptiontemplateid'), (SELECT MAX(PrescriptionTemplateID) FROM PrescriptionTemplate)) AS prescriptiontemplate_next,
       setval(pg_get_serial_sequence('prescription', 'prescriptionid'), (SELECT MAX(PrescriptionID) FROM Prescription)) AS prescription_next;

-- ===========================================================================
-- CHECK: one result table. Every row should say PASS.
-- ===========================================================================
WITH expected_counts AS (
    SELECT 1 AS sort, 'Drug' AS item, 2202 AS expected
    UNION ALL SELECT 2 AS sort, 'ActiveIngredients' AS item, 2008 AS expected
    UNION ALL SELECT 3 AS sort, 'Contains' AS item, 2697 AS expected
    UNION ALL SELECT 4 AS sort, 'SideEffects' AS item, 202 AS expected
    UNION ALL SELECT 5 AS sort, 'HasSideEffects' AS item, 941 AS expected
    UNION ALL SELECT 6 AS sort, 'DrugtoDrugInteraction' AS item, 6684 AS expected
    UNION ALL SELECT 7 AS sort, 'Patient' AS item, 50 AS expected
    UNION ALL SELECT 8 AS sort, 'Doctor' AS item, 8 AS expected
    UNION ALL SELECT 9 AS sort, 'Pharmacist' AS item, 5 AS expected
    UNION ALL SELECT 10 AS sort, 'Disease' AS item, 73 AS expected
    UNION ALL SELECT 11 AS sort, 'Diagnosis' AS item, 120 AS expected
    UNION ALL SELECT 12 AS sort, 'PrescriptionTemplate' AS item, 38 AS expected
    UNION ALL SELECT 13 AS sort, 'Prescription' AS item, 182 AS expected
    UNION ALL SELECT 14 AS sort, 'IsAllergicTo' AS item, 8 AS expected
    UNION ALL SELECT 15 AS sort, 'ToAddress' AS item, 481 AS expected
),
actual_counts AS (
    SELECT 'Drug' AS item, COUNT(*) AS actual FROM Drug
    UNION ALL SELECT 'ActiveIngredients' AS item, COUNT(*) AS actual FROM ActiveIngredients
    UNION ALL SELECT 'Contains' AS item, COUNT(*) AS actual FROM Contains
    UNION ALL SELECT 'SideEffects' AS item, COUNT(*) AS actual FROM SideEffects
    UNION ALL SELECT 'HasSideEffects' AS item, COUNT(*) AS actual FROM HasSideEffects
    UNION ALL SELECT 'DrugtoDrugInteraction' AS item, COUNT(*) AS actual FROM DrugtoDrugInteraction
    UNION ALL SELECT 'Patient' AS item, COUNT(*) AS actual FROM Patient
    UNION ALL SELECT 'Doctor' AS item, COUNT(*) AS actual FROM Doctor
    UNION ALL SELECT 'Pharmacist' AS item, COUNT(*) AS actual FROM Pharmacist
    UNION ALL SELECT 'Disease' AS item, COUNT(*) AS actual FROM Disease
    UNION ALL SELECT 'Diagnosis' AS item, COUNT(*) AS actual FROM Diagnosis
    UNION ALL SELECT 'PrescriptionTemplate' AS item, COUNT(*) AS actual FROM PrescriptionTemplate
    UNION ALL SELECT 'Prescription' AS item, COUNT(*) AS actual FROM Prescription
    UNION ALL SELECT 'IsAllergicTo' AS item, COUNT(*) AS actual FROM IsAllergicTo
    UNION ALL SELECT 'ToAddress' AS item, COUNT(*) AS actual FROM ToAddress
),
scenarios AS (
    SELECT 3 AS prescription_id, 'D1 no alert: on metformin, new amlodipine' AS scenario, 0 AS expect_interaction, 0 AS expect_allergy
    UNION ALL SELECT 6 AS prescription_id, 'D2 allergy: amoxicillin allergy, new amoxicillin' AS scenario, 0 AS expect_interaction, 1 AS expect_allergy
    UNION ALL SELECT 12 AS prescription_id, 'D3 interaction: on warfarin, new ibuprofen' AS scenario, 1 AS expect_interaction, 0 AS expect_allergy
    UNION ALL SELECT 17 AS prescription_id, 'D4 multiple: on warfarin + simvastatin, new clarithromycin' AS scenario, 1 AS expect_interaction, 0 AS expect_allergy
    UNION ALL SELECT 22 AS prescription_id, 'D5 multiple: ibuprofen allergy + on aspirin and digoxin, new ibuprofen' AS scenario, 1 AS expect_interaction, 1 AS expect_allergy
    UNION ALL SELECT 27 AS prescription_id, 'D6 interaction: on clopidogrel, new omeprazole' AS scenario, 1 AS expect_interaction, 0 AS expect_allergy
    UNION ALL SELECT 31 AS prescription_id, 'D7 interaction: on nitroglycerin, new sildenafil' AS scenario, 1 AS expect_interaction, 0 AS expect_allergy
    UNION ALL SELECT 36 AS prescription_id, 'D8 interaction: on spironolactone, new lisinopril' AS scenario, 1 AS expect_interaction, 0 AS expect_allergy
    UNION ALL SELECT 39 AS prescription_id, 'D9 interaction: on sertraline, new tramadol' AS scenario, 1 AS expect_interaction, 0 AS expect_allergy
    UNION ALL SELECT 41 AS prescription_id, 'D10 no alert: clarithromycin ended months ago, new simvastatin' AS scenario, 0 AS expect_interaction, 0 AS expect_allergy
    UNION ALL SELECT 42 AS prescription_id, 'D11 no alert: no medications, no allergies' AS scenario, 0 AS expect_interaction, 0 AS expect_allergy
    UNION ALL SELECT 43 AS prescription_id, 'D12 allergy: carbamazepine SJS on record, new carbamazepine' AS scenario, 0 AS expect_interaction, 1 AS expect_allergy
),
scenario_results AS (
    SELECT s.prescription_id, s.scenario, s.expect_interaction, s.expect_allergy,
           (SELECT COUNT(*)
            FROM Contains pc
            JOIN Diagnosis ad             ON ad.NRIC = dg.NRIC
            JOIN Prescription a           ON a.DiagnosisID = ad.DiagnosisID AND a.ReviewStatus = 'Approved'
                                         AND a.PrescriptionStart <= CURRENT_DATE
                                         AND (a.PrescriptionEnd IS NULL OR a.PrescriptionEnd >= CURRENT_DATE)
            JOIN PrescriptionTemplate at2 ON at2.PrescriptionTemplateID = a.PrescriptionTemplateID
            JOIN Contains ac              ON ac.DrugID = at2.DrugID
            JOIN DrugtoDrugInteraction x  ON x.IngredientID_A = LEAST(pc.IngredientID, ac.IngredientID)
                                         AND x.IngredientID_B = GREATEST(pc.IngredientID, ac.IngredientID)
            WHERE pc.DrugID = t.DrugID) AS interaction_alerts,
           (SELECT COUNT(*)
            FROM Contains pc
            JOIN IsAllergicTo al ON al.NRIC = dg.NRIC AND al.IngredientID = pc.IngredientID
            WHERE pc.DrugID = t.DrugID) AS allergy_alerts
    FROM scenarios s
    JOIN Prescription rx        ON rx.PrescriptionID = s.prescription_id AND rx.ReviewStatus = 'Pending'
    JOIN Diagnosis dg           ON dg.DiagnosisID = rx.DiagnosisID
    JOIN PrescriptionTemplate t ON t.PrescriptionTemplateID = rx.PrescriptionTemplateID
)
SELECT 'counts' AS check_type, e.item, CAST(e.expected AS TEXT) AS expected,
       CAST(COALESCE(a.actual, 0) AS TEXT) AS actual,
       CASE WHEN a.actual = e.expected THEN 'PASS' ELSE 'FAIL' END AS result, e.sort
FROM expected_counts e LEFT JOIN actual_counts a ON a.item = e.item
UNION ALL
SELECT 'scenario', s.scenario,
       CONCAT('interaction ', CASE WHEN s.expect_interaction = 1 THEN 'yes' ELSE 'no' END,
              ', allergy ', CASE WHEN s.expect_allergy = 1 THEN 'yes' ELSE 'no' END),
       COALESCE(CONCAT(r.interaction_alerts, ' interaction, ', r.allergy_alerts, ' allergy'), 'prescription missing'),
       CASE WHEN r.prescription_id IS NOT NULL
             AND (r.interaction_alerts > 0) = (s.expect_interaction = 1)
             AND (r.allergy_alerts > 0) = (s.expect_allergy = 1) THEN 'PASS' ELSE 'FAIL' END,
       100 + s.prescription_id
FROM scenarios s LEFT JOIN scenario_results r ON r.prescription_id = s.prescription_id
ORDER BY sort;

