INSERT INTO DrugtoDrugInteraction (IngredientID_A, IngredientID_B, Symptom, Direction, LabelSaysAvoid, ExampleSentence) VALUES
  (1, 1162, 'drug_exposure', 'increase', FALSE, 'Abacavir, Amprenavir, Efavirenz, Nelfinavir, Nevirapine, Ritonavir, Lopinavir+Ritonavir Combination : Co-administration of these anti-retroviral agents resulted in increased clearance or decreased plasma levels of methadone.'),
  (1, 1257, 'drug_exposure', 'decrease', FALSE, 'Drugs That May Alter Abacavir Blood Concentrations Coadministered Drug and Dose Abacavir Dose n Abacavir Concentrations Concentration of Coadministered Drug AUC Variability Ethanol 0.7 g/kg Single 600 mg 24 ↑41% 90% CI: 35% to 48% ↔ Drugs That May Alter Lamivudine Blood Concentrations Coadministered Drug and Dose Lamivudine Dose n Lamivudine Concentrations Concentration of Coadministered Drug AUC Variability Nelfinavir 750 mg q 8 hr x 7 to 10 days Single 150 mg 11 ↑10% 95% CI: 1% to 20% ↔ Trimethoprim 160 mg/ Sulfamethoxazole 800 mg daily x 5 days Single 300 mg 14 ↑43% 90% CI: 32% to 55% ↔ In vitro data indicate ribavirin reduces phosphorylation of lamivudine, stavudine, and zidovudine.'),
  (1, 1568, 'drug_exposure', 'decrease', FALSE, 'Drugs That May Alter Abacavir Blood Concentrations Coadministered Drug and Dose Abacavir Dose n Abacavir Concentrations Concentration of Coadministered Drug AUC Variability Ethanol 0.7 g/kg Single 600 mg 24 ↑41% 90% CI: 35% to 48% ↔ Drugs That May Alter Lamivudine Blood Concentrations Coadministered Drug and Dose Lamivudine Dose n Lamivudine Concentrations Concentration of Coadministered Drug AUC Variability Nelfinavir 750 mg q 8 hr x 7 to 10 days Single 150 mg 11 ↑10% 95% CI: 1% to 20% ↔ Trimethoprim 160 mg/ Sulfamethoxazole 800 mg daily x 5 days Single 300 mg 14 ↑43% 90% CI: 32% to 55% ↔ In vitro data indicate ribavirin reduces phosphorylation of lamivudine, stavudine, and zidovudine.'),
  (1, 1582, 'drug_exposure', 'increase', FALSE, 'Coadministration with fixed-dose abacavir/dolutegravir/lamivudine resulted in increased riociguat exposure, which may increase the risk of riociguat adverse reactions [see Clinical Pharmacology (12.3) ].'),
  (1, 1723, 'drug_exposure', 'decrease', FALSE, 'Drugs That May Alter Abacavir Blood Concentrations Coadministered Drug and Dose Abacavir Dose n Abacavir Concentrations Concentration of Coadministered Drug AUC Variability Ethanol 0.7 g/kg Single 600 mg 24 ↑41% 90% CI: 35% to 48% ↔ Drugs That May Alter Lamivudine Blood Concentrations Coadministered Drug and Dose Lamivudine Dose n Lamivudine Concentrations Concentration of Coadministered Drug AUC Variability Nelfinavir 750 mg q 8 hr x 7 to 10 days Single 150 mg 11 ↑10% 95% CI: 1% to 20% ↔ Trimethoprim 160 mg/ Sulfamethoxazole 800 mg daily x 5 days Single 300 mg 14 ↑43% 90% CI: 32% to 55% ↔ In vitro data indicate ribavirin reduces phosphorylation of lamivudine, stavudine, and zidovudine.'),
  (1, 1832, 'drug_exposure', 'unspecified', FALSE, 'Nucleoside Reverse Transcriptase Inhibitors: Abacavir ↓ Abacavir AUC by approximately 40% Clinical relevance of reduction in abacavir levels not established.'),
  (1, 1896, 'drug_exposure', 'decrease', FALSE, 'Drugs That May Alter Abacavir Blood Concentrations Coadministered Drug and Dose Abacavir Dose n Abacavir Concentrations Concentration of Coadministered Drug AUC Variability Ethanol 0.7 g/kg Single 600 mg 24 ↑41% 90% CI: 35% to 48% ↔ Drugs That May Alter Lamivudine Blood Concentrations Coadministered Drug and Dose Lamivudine Dose n Lamivudine Concentrations Concentration of Coadministered Drug AUC Variability Nelfinavir 750 mg q 8 hr x 7 to 10 days Single 150 mg 11 ↑10% 95% CI: 1% to 20% ↔ Trimethoprim 160 mg/ Sulfamethoxazole 800 mg daily x 5 days Single 300 mg 14 ↑43% 90% CI: 32% to 55% ↔ In vitro data indicate ribavirin reduces phosphorylation of lamivudine, stavudine, and zidovudine.'),
  (1, 1992, 'drug_exposure', 'increase', FALSE, 'Lamivudine exposure (AUC decreased 15%) and zidovudine exposure (AUC increased 10%) did not show clinically relevant changes with concurrent abacavir.'),
  (5, 1016, 'drug_exposure', 'increase', FALSE, 'Ketoconazole is predicted to increase the AUC of abemaciclib by up to 16-fold [see Clinical Pharmacology ( 12.3 )] .'),
  (5, 1281, 'qt_prolongation', 'unspecified', TRUE, 'Anticancer drugs abemaciclib, ceritinib, dasatinib, encorafenib, ibrutinib, ivosidenib, neratinib, nilotinib, venetoclax, vinblastine, vincristine ↑ anticancer drugs Avoid co-administration of encorafenib or ivosidenib due to potential risk of serious adverse events such as QT interval prolongation.'),
  (5, 1589, 'qt_prolongation', 'unspecified', TRUE, 'Anticancer drugs abemaciclib, ceritinib, dasatinib, encorafenib, ibrutinib, ivosidenib, neratinib, nilotinib, venetoclax, vinblastine, vincristine ↑ anticancer drugs Avoid co-administration of encorafenib or ivosidenib due to potential risk of serious adverse events such as QT interval prolongation.'),
  (6, 532, 'drug_exposure', 'increase', FALSE, 'In a CYP2D6 drug-drug interaction trial, the C max and AUC of dextromethorphan (CYP2D6 substrate) were increased 2.8- and 2.9-fold, respectively, when dextromethorphan was given with abiraterone acetate 1,000 mg daily and prednisone 5 mg twice daily.'),
  (6, 1450, 'drug_exposure', 'increase', FALSE, 'In a CYP2C8 drug-drug interaction trial in healthy subjects, the AUC of pioglitazone (CYP2C8 substrate) was increased by 46% when pioglitazone was given together with a single dose of 1,000 mg abiraterone acetate.'),
  (6, 1494, 'drug_exposure', 'increase', FALSE, 'In a CYP2D6 drug-drug interaction trial, the C max and AUC of dextromethorphan (CYP2D6 substrate) were increased 2.8- and 2.9-fold, respectively, when dextromethorphan was given with abiraterone acetate 1,000 mg daily and prednisone 5 mg twice daily.'),
  (6, 1573, 'drug_exposure', 'decrease', FALSE, 'The co-administration of rifampin, a strong CYP3A4 inducer, decreased exposure of abiraterone by 55%.'),
  (8, 767, 'drug_exposure', 'increase', FALSE, 'Abrocitinib: Drug interaction studies indicate that when coadministered with fluconazole (strong inhibitor of CYP2C19; moderate inhibitor of CYP2C9 and CYP3A4), the systemic exposure of abrocitinib and its active metabolites increased (See CLINICAL PHARMACOLOGY).'),
  (11, 552, 'drug_exposure', 'increase', FALSE, 'Acarbose may affect digoxin bioavailability and may require dose adjustment of digoxin by 16% (90% confidence interval: 8-23%), decrease mean C max of digoxin by 26% (90% confidence interval: 16–34%) and decreases mean trough concentrations of digoxin by 9% (90% confidence limit: 19% decrease to 2% increase).'),
  (11, 960, 'hypoglycemia', 'increase', FALSE, 'Acarbose given in combination with a sulfonylurea or insulin may cause a further lowering of blood glucose and may increase the potential for hypoglycemia.'),
  (11, 1160, 'drug_exposure', 'unspecified', FALSE, 'The amount of metformin absorbed while taking acarbose was bioequivalent to the amount absorbed when taking placebo, as indicated by the plasma AUC values.'),
  (11, 1273, 'hyperglycemia', 'unspecified', FALSE, 'Acarbose: Nifedipine tends to produce hyperglycemia and may lead to loss of glucose control.'),
  (14, 96, 'drug_exposure', 'increase', FALSE, 'The concomitant use of acetaminophen and codeine phosphate tablets with all cytochrome P450 2D6 inhibitors (e.g., amiodarone, quinidine) may result in an increase in codeine plasma concentrations and a decrease in active metabolite morphine plasma concentration which could result in an analgesic efficacy reduction or symptoms of opioid withdrawal.'),
  (14, 98, 'drug_exposure', 'decrease', FALSE, 'and amitriptyline (CYP2D6 inhibitors), and ketoconazole and erythromycin (CYP3A4 inhibitors), may reduce metabolic clearance of tramadol increasing the risk for serious adverse events including seizures and serotonin syndrome.'),
  (14, 98, 'serotonin_syndrome', 'decrease', FALSE, 'and amitriptyline (CYP2D6 inhibitors), and ketoconazole and erythromycin (CYP3A4 inhibitors), may reduce metabolic clearance of tramadol increasing the risk for serious adverse events including seizures and serotonin syndrome.'),
  (14, 138, 'hypertension', 'decrease', FALSE, 'Examples of Drugs Associated with Methemoglobinemia: Class Examples Nitrates/Nitrites nitric oxide, nitroglycerin, nitroprusside, nitrous oxide Local anesthetics articaine, benzocaine, bupivacaine, lidocaine, mepivacaine, prilocaine, procaine, ropivacaine, tetracaine Antineoplastic agents cyclophosphamide, flutamide, hydroxyurea, ifosfamide, rasburicase Antibiotics dapsone, nitrofurantoin, para-aminosalicylic acid, sulfonamides Antimalarials chloroquine, primaquine Anticonvulsants phenobarbital, phenytoin, sodium valproate Other drugs acetaminophen, metoclopramide, quinine, sulfasalazine Monoamine Oxidase Inhibitors, Nonselective Beta-Adrenergic Antagonists, or Tricyclic Antidepressants: May produce severe, prolonged hypertension ( 7 ) Phenothiazines and Butyrophenones: May reduce or reverse the pressor effect of epinephrine ( 7 )'),
  (14, 270, 'respiratory_depression', 'increase', FALSE, 'Examples: butorphanol, nalbuphine, pentazocine, buprenorphine Muscle Relaxants Clinical Impact: Codeine may enhance the neuromuscular blocking action of skeletal muscle relaxants and produce an increased degree of respiratory depression.'),
  (14, 271, 'cns_depression', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 271, 'drug_exposure', 'increase', FALSE, 'Examples: Quinidine, fluoxetine, paroxetine and bupropion Inhibitors of CYP3A4 Clinical Impact: The concomitant use of tramadol hydrochloride and acetaminophen and CYP3A4 inhibitors can increase the plasma concentration of tramadol and may result in a greater amount of metabolism via CYP2D6 and greater levels of M1.'),
  (14, 271, 'hypotension', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 271, 'respiratory_depression', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 274, 'drug_exposure', 'decrease', FALSE, 'Drugs that Decrease busulfan Clearance: Metronidazole, itraconazole, Iron chelating agent acetaminophen.'),
  (14, 278, 'respiratory_depression', 'increase', FALSE, 'Examples: butorphanol, nalbuphine, pentazocine, buprenorphine Muscle Relaxants Clinical Impact: Codeine may enhance the neuromuscular blocking action of skeletal muscle relaxants and produce an increased degree of respiratory depression.'),
  (14, 310, 'cns_depression', 'increase', FALSE, 'Examples: Rifampin, carbamazepine, phenytoin Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 310, 'drug_exposure', 'decrease', FALSE, 'The concomitant use of hydrocodone bitartrate and acetaminophen tablets and CYP3A4 inducers, such as rifampin, carbamazepine, and phenytoin, can decrease the plasma concentration of hydrocodone'),
  (14, 310, 'hepatotoxicity', 'increase', FALSE, 'The potential for hepatotoxicity with Acetaminophen also may be increased in patients receiving anticonvulsants that induce hepatic microsomal enzymes (including phenytoin, barbiturates, and carbamazepine) or isoniazide.'),
  (14, 310, 'hypotension', 'increase', FALSE, 'Examples: Rifampin, carbamazepine, phenytoin Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 310, 'respiratory_depression', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 310, 'seizure_risk', 'unspecified', TRUE, 'Because carbamazepine increases tramadol metabolism and because of the seizure risk associated with tramadol, concomitant administration of tramadol hydrochloride and acetaminophen and carbamazepine is not recommended.'),
  (14, 310, 'serotonin_syndrome', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 360, 'cns_depression', 'increase', FALSE, 'Butalbital and acetaminophen may enhance the effects of:other narcotic analgesics, alcohol, general anesthetics, tranquilizers such as chlordiazepoxide, sedative-hypnotics, or other CNS depressants, causing increased CNS depression.'),
  (14, 412, 'cns_depression', 'unspecified', FALSE, 'Concomitant use of clozapine and lorazepam may produce marked sedation, excessive salivation, hypotension, ataxia, delirium, and respiratory arrest.'),
  (14, 412, 'hypotension', 'unspecified', FALSE, 'Concomitant use of clozapine and lorazepam may produce marked sedation, excessive salivation, hypotension, ataxia, delirium, and respiratory arrest.'),
  (14, 446, 'respiratory_depression', 'increase', FALSE, 'Oxycodone and acetaminophen tablets may enhance the neuromuscular blocking action of skeletal muscle relaxants (e.g., cyclobenzaprine, metaxalone) and produce an increase in the degree of respiratory depression.'),
  (14, 446, 'seizure_risk', 'increase', FALSE, 'Tricyclic antidepressants may enhance the seizure risk in patients taking tramadol ULTRAM® (tramadol HCI tablets, Ortho-McNeil Pharmaceutical) ULTRACET® (tramadol HCI and acetaminophen tablets, Ortho-McNeil Pharmaceutical) .'),
  (14, 446, 'serotonin_syndrome', 'unspecified', FALSE, 'The concomitant use of opioids with other drugs that affect the serotonergic neurotransmitter system, such as selective serotonin reuptake inhibitors (SSRIs), serotonin and norepinephrine reuptake inhibitors (SNRIs), tricyclic antidepressants (TCAs), triptans, 5-HT3 receptor antagonists, drugs that affect the serotonin neurotransmitter system (e.g., mirtazapine, trazodone, tramadol), certain muscle relaxants (i.e., cyclobenzaprine, metaxalone), monoamine oxidase (MAO) inhibitors (those intended to treat psychiatric disorders and also others, such as linezolid and intravenous methylene blue), has resulted in serotonin syndrome'),
  (14, 450, 'nephrotoxicity', 'increase', FALSE, 'Cyclosporine Clinical Impact: Concomitant use of NSAIDS and cyclosporine may increase cyclosporine''s nephrotoxicity.'),
  (14, 516, 'drug_exposure', 'increase', FALSE, 'Decreased plasma concentrations of acetaminophen and increased clearance of temazepam, salicylic acid, morphine and clofibric acid have been noted when these drugs were administered with oral contraceptives.'),
  (14, 516, 'seizure_risk', 'increase', FALSE, 'Some medicines and grapefruit juice may increase your level of the hormone ethinyl estradiol if used together, including: acetaminophen ascorbic acid medicines that affect how your liver breaks down other medicines (itraconazole, ketoconazole, voriconazole, and fluconazole) certain HIV medicines (atazanavir, indinavir) atorvastatin rosuvastatin etravirine Hormonal birth control methods may interact with lamotrigine, a seizure medicine used for epilepsy.'),
  (14, 550, 'hepatotoxicity', 'unspecified', FALSE, 'Since acetaminophen in high doses has been associated with hepatotoxicity, concomitant administration of diflunisal tablets and acetaminophen should be used cautiously, with careful monitoring of patients.'),
  (14, 552, 'drug_exposure', 'increase', FALSE, 'Digoxin Clinical Impact: The concomitant use of ibuprofen with digoxin has been reported to increase the serum concentration and prolong the half-life of digoxin.'),
  (14, 566, 'drug_exposure', 'decrease', FALSE, 'Co-administration of caffeine and disulfiram may lead to a substantial decrease in caffeine clearance.'),
  (14, 593, 'drug_exposure', 'increase', FALSE, 'Decreased plasma concentrations of acetaminophen and increased clearance on temazepam, salicylic acid, morphine, and clofibric acid have been noted when these drugs were administered with oral contraceptives.'),
  (14, 677, 'drug_exposure', 'increase', FALSE, 'Administration of CYP3A4 inhibitors, such as ketoconazole and erythromycin, or inducers, such as rifampin and St. John''s Wort, with tramadol hydrochloride and acetaminophen may affect the metabolism of tramadol leading to altered tramadol exposure.'),
  (14, 677, 'respiratory_depression', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 677, 'serotonin_syndrome', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 700, 'drug_exposure', 'increase', FALSE, 'Ascorbic acid and acetaminophen may increase systemic exposure of ethinyl estradiol, possibly by inhibition of conjugation.'),
  (14, 700, 'seizure_risk', 'increase', FALSE, 'Some medicines and grapefruit juice may increase your level of the hormone ethinyl estradiol if used together, including: acetaminophen ascorbic acid medicines that affect how your liver breaks down other medicines (itraconazole, ketoconazole, voriconazole, and fluconazole) certain HIV medicines (atazanavir, indinavir) atorvastatin rosuvastatin etravirine Hormonal birth control methods may interact with lamotrigine, a seizure medicine used for epilepsy.'),
  (14, 706, 'drug_exposure', 'increase', FALSE, 'Decreased plasma concentrations of acetaminophen and increased clearance of temazepam, salicylic acid, morphine and clofibric acid have been noted when these drugs were administered with oral contraceptives.'),
  (14, 735, 'drug_exposure', 'increase', FALSE, 'Decreased plasma concentrations of acetaminophen and increased clearance of temazepam, salicylic acid, morphine, and clofibric acid have been noted when these drugs were administered with oral contraceptives.'),
  (14, 781, 'cns_depression', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 781, 'drug_exposure', 'increase', FALSE, 'Examples: Quinidine, fluoxetine, paroxetine and bupropion Inhibitors of CYP3A4 Clinical Impact: The concomitant use of tramadol hydrochloride and acetaminophen and CYP3A4 inhibitors can increase the plasma concentration of tramadol and may result in a greater amount of metabolism via CYP2D6 and greater levels of M1.'),
  (14, 781, 'hypotension', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 781, 'respiratory_depression', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 781, 'serotonin_syndrome', 'decrease', FALSE, 'Concomitant administration of CYP2D6 and/or CYP3A4 inhibitors (see CLINICAL PHARMACOLOGY, Pharmacokinetics ), such as quinidine, fluoxetine, paroxetine and amitriptyline (CYP2D6 inhibitors), and ketoconazole and erythromycin (CYP3A4 inhibitors), may reduce metabolic clearance of tramadol increasing the risk for serious adverse events including seizures and serotonin syndrome.'),
  (14, 793, 'drug_exposure', 'increase', FALSE, 'Decreased plasma concentrations of acetaminophen and increased clearance of temazepam, salicylic acid, morphine, and clofibric acid, due to induction of conjugation (particularly glucuronidation), have been noted when these drugs were administered with oral contraceptives.'),
  (14, 816, 'cns_depression', 'increase', FALSE, 'Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants (e.g., benzodiazepines and other sedative/hypnotics, anxiolytics, tranquilizers, muscle relaxants, general anesthetics, antipsychotics, gabapentinoids (gabapentin or pregabalin), other opioids), including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 816, 'hypotension', 'increase', FALSE, 'Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants (e.g., benzodiazepines and other sedative/hypnotics, anxiolytics, tranquilizers, muscle relaxants, general anesthetics, antipsychotics, gabapentinoids (gabapentin or pregabalin), other opioids), including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 816, 'respiratory_depression', 'increase', FALSE, 'Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants (e.g., benzodiazepines and other sedative/hypnotics, anxiolytics, tranquilizers, muscle relaxants, general anesthetics, antipsychotics, gabapentinoids (gabapentin or pregabalin), other opioids), including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 894, 'respiratory_depression', 'unspecified', FALSE, 'If urgent use of an opioid is necessary, use test doses and frequent titration of small doses of other opioids (such as oxycodone, hydrocodone, oxymorphone, hydromorphone, or buprenorphine) to treat pain while closely monitoring blood pressure and signs and symptoms of CNS and respiratory depression.'),
  (14, 997, 'hepatotoxicity', 'unspecified', FALSE, 'Studies have demonstrated that pretreatment with isoniazid potentiates acetaminophen hepatotoxicity in rats 1,2 .'),
  (14, 1016, 'drug_exposure', 'increase', FALSE, 'Administration of CYP3A4 inhibitors, such as ketoconazole and erythromycin, or inducers, such as rifampin and St. John''s Wort, with tramadol hydrochloride and acetaminophen may affect the metabolism of tramadol leading to altered tramadol exposure.'),
  (14, 1016, 'respiratory_depression', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 1016, 'serotonin_syndrome', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 1067, 'drug_exposure', 'increase', FALSE, 'Ascorbic acid and acetaminophen may increase systemic exposure of EE possibly by inhibition of conjugation.'),
  (14, 1077, 'respiratory_depression', 'unspecified', FALSE, 'The concomitant use of opioids and MAOIs, such as phenelzine, tranylcypromine, linezolid, may manifest as serotonin syndrome or opioid toxicity (e.g., respiratory depression, coma)'),
  (14, 1077, 'serotonin_syndrome', 'unspecified', FALSE, 'The concomitant use of opioids and MAOIs, such as phenelzine, tranylcypromine, linezolid, maymanifest as serotonin syndrome or opioid toxicity.'),
  (14, 1084, 'drug_exposure', 'increase', FALSE, 'The mean minimum lithium concentration increased 15%, and the renal clearance decreased by approximately 20%.'),
  (14, 1096, 'cns_depression', 'unspecified', FALSE, 'Concomitant use of clozapine and lorazepam may produce marked sedation, excessive salivation, hypotension, ataxia, delirium, and respiratory arrest.'),
  (14, 1096, 'drug_exposure', 'increase', FALSE, 'Concurrent administration of lorazepam with valproate results in increased plasma concentrations and reduced clearance of lorazepam.'),
  (14, 1096, 'hypotension', 'unspecified', FALSE, 'Concomitant use of clozapine and lorazepam may produce marked sedation, excessive salivation, hypotension, ataxia, delirium, and respiratory arrest.'),
  (14, 1159, 'respiratory_depression', 'increase', FALSE, 'Oxycodone and acetaminophen tablets may enhance the neuromuscular blocking action of skeletal muscle relaxants (e.g., cyclobenzaprine, metaxalone) and produce an increase in the degree of respiratory depression.'),
  (14, 1159, 'serotonin_syndrome', 'unspecified', FALSE, 'The concomitant use of opioids with other drugs that affect the serotonergic neurotransmitter system, such as selective serotonin reuptake inhibitors (SSRIs), serotonin and norepinephrine reuptake inhibitors (SNRIs), tricyclic antidepressants (TCAs), triptans, 5-HT3 receptor antagonists, drugs that affect the serotonin neurotransmitter system (e.g., mirtazapine, trazodone, tramadol), certain muscle relaxants (i.e.,cyclobenzaprine, metaxalone), monoamine oxidase (MAO) inhibitors (those intended to treat psychiatric disorders and also others, such as linezolid and intravenous methylene blue), has resulted in serotonin syndrome'),
  (14, 1176, 'serotonin_syndrome', 'unspecified', FALSE, 'The concomitant use of opioids with other drugs that affect the serotonergic neurotransmitter system, such as selective serotonin reuptake inhibitors (SSRIs), serotonin and norepinephrine reuptake inhibitors (SNRIs), tricyclic antidepressants (TCAs), triptans, 5-HT3 receptor antagonists, drugs that affect the serotonin neurotransmitter system (e.g., mirtazapine, trazodone, tramadol), and monoamine oxidase (MAO) inhibitors (those intended to treat psychiatric disorders and also others, such as linezolid and intravenous methylene blue), has resulted in serotonin syndrome'),
  (14, 1208, 'serotonin_syndrome', 'unspecified', FALSE, 'The concomitant use of opioids with other drugs that affect the serotonergic neurotransmitter system, such as selective serotonin reuptake inhibitors (SSRIs), serotonin and norepinephrine reuptake inhibitors (SNRIs), tricyclic antidepressants (TCAs), triptans, 5-HT3 receptor antagonists, drugs that affect the serotonin neurotransmitter system (e.g., mirtazapine, trazodone, tramadol), and monoamine oxidase (MAO) inhibitors (those intended to treat psychiatric disorders and also others, such as linezolid and intravenous methylene blue), has resulted in serotonin syndrome'),
  (14, 1223, 'drug_exposure', 'increase', FALSE, 'The concomitant use of acetaminophen and codeine phosphate tablets with all cytochrome P450 2D6 inhibitors (e.g., amiodarone, quinidine) may result in an increase in codeine plasma concentrations and a decrease in active metabolite morphine plasma concentration which could result in an analgesic efficacy reduction or symptoms of opioid withdrawal.'),
  (14, 1223, 'respiratory_depression', 'increase', FALSE, 'The concomitant use of acetaminophen and codeine phosphate tablets with all cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in codeine plasma concentrations with subsequently greater metabolism by cytochrome P450 2D6, resulting in greater morphine levels, which could increase or prolong adverse reactions and may cause potentially fatal respiratory depression.'),
  (14, 1236, 'respiratory_depression', 'increase', FALSE, 'Examples: butorphanol, nalbuphine, pentazocine, buprenorphine Muscle Relaxants Clinical Impact: Codeine may enhance the neuromuscular blocking action of skeletal muscle relaxants and produce an increased degree of respiratory depression.'),
  (14, 1238, 'respiratory_depression', 'unspecified', FALSE, 'An opioid overdose reversal agent, such as naloxone or nalmefene, must be available for reversal of opioid-induced respiratory depression in the neonate.'),
  (14, 1240, 'respiratory_depression', 'unspecified', FALSE, 'An opioid antagonist, such as naloxone, must be available for reversal of opioid-induced respiratory depression in the neonate.'),
  (14, 1297, 'bleeding_risk', 'unspecified', FALSE, 'Intervention: Monitor patients with concomitant use of COMBOGESIC with anticoagulants (e.g., warfarin), antiplatelet agents (e.g., aspirin), selective serotonin reuptake inhibitors (SSRIs), and serotonin norepinephrine reuptake inhibitors (SNRIs) for signs of bleeding [ see Warnings and Precautions (5.12) ].'),
  (14, 1297, 'serotonin_syndrome', 'unspecified', FALSE, 'The concomitant use of opioids with other drugs that affect the serotonergic neurotransmitter system, such as selective serotonin reuptake inhibitors (SSRIs), serotonin and norepinephrine reuptake inhibitors (SNRIs), tricyclic antidepressants (TCAs), triptans, 5-HT3 receptor antagonists, drugs that affect the serotonin neurotransmitter system (e.g., mirtazapine, trazodone, tramadol), and monoamine oxidase (MAO) inhibitors (those intended to treat psychiatric disorders and also others, such as linezolid and intravenous methylene blue), has resulted in serotonin syndrome'),
  (14, 1298, 'drug_exposure', 'increase', FALSE, 'Decreased plasma concentrations of acetaminophen and increased clearance of temazepam, salicylic acid, morphine, and clofibric acid have been noted when these drugs were administered with oral contraceptives.'),
  (14, 1299, 'drug_exposure', 'increase', FALSE, 'Decreased plasma concentrations of acetaminophen and increased clearance of temazepam, salicylic acid, morphine and clofibric acid, due to induction of conjugation, have been noted when drugs were administered with oral contraceptives.'),
  (14, 1355, 'hypertension', 'unspecified', TRUE, 'Examples of Drugs Associated with Methemoglobinemia: Class Examples Nitrates/Nitrites nitric oxide, nitroglycerin, nitroprusside, nitrous oxide Local anesthetics articaine, benzocaine, bupivacaine, lidocaine, mepivacaine, prilocaine, procaine, ropivacaine, tetracaine Antineoplastic agents cyclophosphamide, flutamide, hydroxyurea, ifosfamide, rasburicase Antibiotics dapsone, nitrofurantoin, para-aminosalicylic acid, sulfonamides Antimalarials chloroquine, primaquine Anticonvulsants phenobarbital, phenytoin, sodium valproate, Other drugs acetaminophen, metoclopramide, quinine, sulfasalazine Use of KOVANAZE in combination with monoamine oxidase inhibitors (MAOIs), nonselective beta adrenergic antagonists, or tricyclic antidepressants may cause hypertension and is not recommended.'),
  (14, 1356, 'respiratory_depression', 'unspecified', FALSE, 'If urgent use of an opioid is necessary, use test doses and frequent titration of small doses of other opioids (such as oxycodone, hydrocodone, oxymorphone or buprenorphine) to treat pain while closely monitoring blood pressure and signs and symptoms of CNS and respiratory depression.'),
  (14, 1379, 'cns_depression', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1379, 'drug_exposure', 'increase', FALSE, 'Examples: Quinidine, fluoxetine, paroxetine and bupropion Inhibitors of CYP3A4 Clinical Impact: The concomitant use of tramadol hydrochloride and acetaminophen and CYP3A4 inhibitors can increase the plasma concentration of tramadol and may result in a greater amount of metabolism via CYP2D6 and greater levels of M1.'),
  (14, 1379, 'hypotension', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1379, 'respiratory_depression', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1379, 'serotonin_syndrome', 'decrease', FALSE, 'Concomitant administration of CYP2D6 and/or CYP3A4 inhibitors (see CLINICAL PHARMACOLOGY, Pharmacokinetics ), such as quinidine, fluoxetine, paroxetine and amitriptyline (CYP2D6 inhibitors), and ketoconazole and erythromycin (CYP3A4 inhibitors), may reduce metabolic clearance of tramadol increasing the risk for serious adverse events including seizures and serotonin syndrome.'),
  (14, 1406, 'drug_exposure', 'unspecified', FALSE, 'Intervention: During concomitant use of COMBOGESIC and pemetrexed, in patients with renal impairment whose creatinine clearance ranges from 45 to 79 mL/min, monitor for myelosuppression, renal and GI toxicity.'),
  (14, 1417, 'respiratory_depression', 'increase', FALSE, 'Examples: butorphanol, nalbuphine, pentazocine, buprenorphine Muscle Relaxants Clinical Impact: Codeine may enhance the neuromuscular blocking action of skeletal muscle relaxants and produce an increased degree of respiratory depression.'),
  (14, 1434, 'respiratory_depression', 'unspecified', FALSE, 'The concomitant use of opioids and MAOIs, such as phenelzine, tranylcypromine, linezolid, may manifest as serotonin syndrome or opioid toxicity (e.g., respiratory depression, coma)'),
  (14, 1434, 'serotonin_syndrome', 'unspecified', FALSE, 'The concomitant use of opioids and MAOIs, such as phenelzine, tranylcypromine, linezolid, maymanifest as serotonin syndrome or opioid toxicity.'),
  (14, 1436, 'seizure_risk', 'unspecified', FALSE, 'The infant was given phenobarbital 5 mg/kg, which was tapered without further seizure or other withdrawal symptoms.'),
  (14, 1441, 'cns_depression', 'increase', FALSE, 'Examples: Rifampin, carbamazepine, phenytoin Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1441, 'drug_exposure', 'decrease', FALSE, 'The concomitant use of hydrocodone bitartrate and acetaminophen tablets and CYP3A4 inducers, such as rifampin, carbamazepine, and phenytoin, can decrease the plasma concentration of hydrocodone'),
  (14, 1441, 'hepatotoxicity', 'increase', FALSE, 'The potential for hepatotoxicity with Acetaminophen also may be increased in patients receiving anticonvulsants that induce hepatic microsomal enzymes (including phenytoin, barbiturates, and carbamazepine) or isoniazide.'),
  (14, 1441, 'hypotension', 'increase', FALSE, 'Examples: Rifampin, carbamazepine, phenytoin Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1441, 'respiratory_depression', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 1441, 'serotonin_syndrome', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 1495, 'cns_depression', 'increase', FALSE, 'Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants (e.g., benzodiazepines and other sedative/hypnotics, anxiolytics, tranquilizers, muscle relaxants, general anesthetics, antipsychotics, gabapentinoids (gabapentin or pregabalin), other opioids), including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1495, 'hypotension', 'increase', FALSE, 'Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants (e.g., benzodiazepines and other sedative/hypnotics, anxiolytics, tranquilizers, muscle relaxants, general anesthetics, antipsychotics, gabapentinoids (gabapentin or pregabalin), other opioids), including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1495, 'respiratory_depression', 'increase', FALSE, 'Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants (e.g., benzodiazepines and other sedative/hypnotics, anxiolytics, tranquilizers, muscle relaxants, general anesthetics, antipsychotics, gabapentinoids (gabapentin or pregabalin), other opioids), including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1497, 'hypertension', 'unspecified', FALSE, 'Class Examples Nitrates/Nitrites nitric oxide, nitroglycerin, nitroprusside, nitrous oxide Local anesthetics articaine, benzocaine, bupivacaine, lidocaine, mepivacaine, prilocaine, procaine, ropivacaine, tetracaine Antineoplastic Agents cyclophosphamide, flutamide, hydroxyurea, ifosfamide, rasburicase Antibiotics dapsone, nitrofurantoin, para-aminosalicylic acid, sulfonamides Antimalarials chloroquine, primaquine Anticonvulsants Phenobarbital, phenytoin, sodium valproate Other drugs acetaminophen, metoclopramide, quinine, sulfasalazine Concurrent administration of vasopressor drugs and ergot-type oxytocic drugs may cause severe, persistent hypertension or cerebrovascular accidents.'),
  (14, 1497, 'hypotension', 'unspecified', FALSE, 'Class Examples Nitrates/Nitrites nitric oxide, nitroglycerin, nitroprusside, nitrous oxide Local anesthetics articaine, benzocaine, bupivacaine, lidocaine, mepivacaine, prilocaine, procaine, ropivacaine, tetracaine Antineoplastic Agents cyclophosphamide, flutamide, hydroxyurea, ifosfamide, rasburicase Antibiotics dapsone, nitrofurantoin, para-aminosalicylic acid, sulfonamides Antimalarials chloroquine, primaquine Anticonvulsants phenobarbital, phenytoin, sodium valproate Other drugs acetaminophen, metoclopramide, quinine, sulfasalazine The administration of local anesthetic injections containing epinephrine or norepinephrine to patients receiving monoamine oxidase inhibitors, tricyclic antidepressants or phenothiazines may produce severe, prolonged hypotension or hypertension.'),
  (14, 1500, 'drug_exposure', 'increase', FALSE, 'Concurrent administration of lorazepam with probenecid may result in a more rapid onset or prolonged effect of lorazepam due to increased half-life and decreased total clearance.'),
  (14, 1526, 'cns_depression', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1526, 'drug_exposure', 'increase', FALSE, 'Examples: Quinidine, fluoxetine, paroxetine and bupropion Inhibitors of CYP3A4 Clinical Impact: The concomitant use of tramadol hydrochloride and acetaminophen and CYP3A4 inhibitors can increase the plasma concentration of tramadol and may result in a greater amount of metabolism via CYP2D6 and greater levels of M1.'),
  (14, 1526, 'hypotension', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1526, 'respiratory_depression', 'increase', FALSE, 'Examples: paroxetine, fluoxetine, bupropion, quinidine Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1526, 'serotonin_syndrome', 'decrease', FALSE, 'Concomitant administration of CYP2D6 and/or CYP3A4 inhibitors (see CLINICAL PHARMACOLOGY, Pharmacokinetics ), such as quinidine, fluoxetine, paroxetine and amitriptyline (CYP2D6 inhibitors), and ketoconazole and erythromycin (CYP3A4 inhibitors), may reduce metabolic clearance of tramadol increasing the risk for serious adverse events including seizures and serotonin syndrome.'),
  (14, 1573, 'cns_depression', 'increase', FALSE, 'Examples: Rifampin, carbamazepine, phenytoin Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1573, 'drug_exposure', 'decrease', FALSE, 'The concomitant use of hydrocodone bitartrate and acetaminophen tablets and CYP3A4 inducers, such as rifampin, carbamazepine, and phenytoin, can decrease the plasma concentration of hydrocodone'),
  (14, 1573, 'hypotension', 'increase', FALSE, 'Examples: Rifampin, carbamazepine, phenytoin Benzodiazepines and Other Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death.'),
  (14, 1573, 'respiratory_depression', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 1573, 'serotonin_syndrome', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 1580, 'drug_exposure', 'decrease', FALSE, 'Coadministration with acetaminophen reduced the peak concentration and AUC values for rimantadine by approximately 11%.'),
  (14, 1589, 'drug_exposure', 'increase', FALSE, 'Examples: Macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g. ketoconazole), protease inhibitors (e.g., ritonavir) CYP3A4 Inducers Clinical Impact: The concomitant use of tramadol hydrochloride and acetaminophen and CYP3A4 inducers can decrease the plasma concentration of tramadol'),
  (14, 1589, 'respiratory_depression', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 1589, 'serotonin_syndrome', 'increase', FALSE, 'The concomitant use of tramadol hydrochloride and acetaminophen with cytochrome P450 3A4 inhibitors, such as macrolide antibiotics (e.g., erythromycin), azole-antifungal agents (e.g., ketoconazole), and protease inhibitors (e.g., ritonavir) or discontinuation of a cytochrome P450 3A4 inducer such as rifampin, carbamazepine, and phenytoin, may result in an increase in tramadol plasma concentrations, which could increase or prolong adverse reactions, increase the risk for serious adverse events including seizures and serotonin syndrome, and may cause potentially fatal respiratory depression.'),
  (14, 1633, 'drug_exposure', 'decrease', FALSE, 'Other Drugs Clinical effect Concomitant use of CHCs may decrease systemic exposure of acetaminophen, morphine, salicylic acid, and temazepam.'),
  (14, 1807, 'hypertension', 'unspecified', TRUE, 'Examples of Drugs Associated with Methemoglobinemia: Class Examples Nitrates/Nitrites nitric oxide, nitroglycerin, nitroprusside, nitrous oxide Local anesthetics articaine, benzocaine, bupivacaine, lidocaine, mepivacaine, prilocaine, procaine, ropivacaine, tetracaine Antineoplastic agents cyclophosphamide, flutamide, hydroxyurea, ifosfamide, rasburicase Antibiotics dapsone, nitrofurantoin, para-aminosalicylic acid, sulfonamides Antimalarials chloroquine, primaquine Anticonvulsants phenobarbital, phenytoin, sodium valproate, Other drugs acetaminophen, metoclopramide, quinine, sulfasalazine Use of KOVANAZE in combination with monoamine oxidase inhibitors (MAOIs), nonselective beta adrenergic antagonists, or tricyclic antidepressants may cause hypertension and is not recommended.'),
  (14, 1867, 'respiratory_depression', 'unspecified', FALSE, 'The concomitant use of opioids and MAOIs, such as phenelzine, tranylcypromine, linezolid, may manifest as serotonin syndrome or opioid toxicity (e.g., respiratory depression, coma)'),
  (14, 1867, 'serotonin_syndrome', 'unspecified', FALSE, 'The concomitant use of opioids and MAOIs, such as phenelzine, tranylcypromine, linezolid, maymanifest as serotonin syndrome or opioid toxicity.'),
  (14, 1877, 'serotonin_syndrome', 'unspecified', FALSE, 'The concomitant use of opioids with other drugs that affect the serotonergic neurotransmitter system, such as selective serotonin reuptake inhibitors (SSRIs), serotonin and norepinephrine reuptake inhibitors (SNRIs), tricyclic antidepressants (TCAs), triptans, 5-HT3 receptor antagonists, drugs that affect the serotonin neurotransmitter system (e.g., mirtazapine, trazodone, tramadol), and monoamine oxidase (MAO) inhibitors (those intended to treat psychiatric disorders and also others, such as linezolid and intravenous methylene blue), has resulted in serotonin syndrome'),
  (14, 1929, 'drug_exposure', 'increase', FALSE, 'Concurrent administration of lorazepam with valproate results in increased plasma concentrations and reduced clearance of lorazepam.'),
  (14, 1977, 'bleeding_risk', 'increase', FALSE, 'Chronic oral acetaminophen use at a dose of 4000 mg/day has been shown to cause an increase in international normalized ratio (INR) in some patients who have been stabilized on sodium warfarin as an anticoagulant.'),
  (14, 1992, 'drug_exposure', 'decrease', FALSE, 'The pharmacologic effects of zidovudine may be decreased because of enhanced nonhepatic or renal clearance of zidovudine.'),
  (15, 145, 'drug_exposure', 'increase', FALSE, 'Acetazolamide, methazolamide Methotrexate Clinical Impact: Aspirin may enhance the toxicity of methotrexate by displacing it from its plasma protein binding sites and/or reducing its renal clearance.'),
  (15, 275, 'drug_exposure', 'increase', FALSE, 'Acetazolamide, methazolamide Methotrexate Clinical Impact: Aspirin may enhance the toxicity of methotrexate by displacing it from its plasma protein binding sites and/or reducing its renal clearance.'),
  (15, 416, 'drug_exposure', 'increase', FALSE, 'Acetazolamide, methazolamide Methotrexate Clinical Impact: Aspirin may enhance the toxicity of methotrexate by displacing it from its plasma protein binding sites and/or reducing its renal clearance.'),
  (15, 1160, 'drug_exposure', 'decrease', FALSE, 'Examples: Topiramate, zonisamide, acetazolamide or dichlorphenamide Drugs that Reduce Metformin Clearance Clinical Impact: Concomitant use of drugs that interfere with common renal tubular transport systems involved in the renal elimination of metformin (e.g., organic cationic transporter-2'),
  (24, 1149, 'cns_depression', 'unspecified', FALSE, 'Intervention: If concomitant use of acyclovir and meperidine hydrochloride tablets is necessary, evaluate patients for respiratory depression and sedation at frequent intervals.'),
  (24, 1149, 'respiratory_depression', 'unspecified', FALSE, 'Intervention: If concomitant use of acyclovir and meperidine hydrochloride tablets is necessary, evaluate patients for respiratory depression and sedation at frequent intervals.'),
  (24, 1230, 'drug_exposure', 'decrease', FALSE, 'Coadministration of mycophenolate mofetil (1 g) and acyclovir (800 mg) to 12 healthy volunteers resulted in no significant change in MPA AUC and C max .'),
  (24, 1500, 'drug_exposure', 'increase', FALSE, 'Coadministration of probenecid with acyclovir has been shown to increase the mean acyclovir half-life and the area under the concentration-time curve.'),
  (24, 1977, 'bleeding_risk', 'increase', FALSE, 'Table 2 Examples of CYP450 Interactions with Warfarin Enzyme Inhibitors Inducers CYP2C9 amiodarone, capecitabine, cotrimoxazole, etravirine, fluconazole, fluvastatin, fluvoxamine, metronidazole miconazole, oxandrolone, sulfinpyrazone, tigecycline, voriconazole, zafirlukast aprepitant, bosentan, carbamazepine, phenobarbital, rifampin CYP1A2 acyclovir, allopurinol, caffeine, cimetidine, ciprofloxacin, disulfiram, enoxacin, famotidine, fluvoxamine, methoxsalen, mexiletine, norfloxacin, oral contraceptives, phenylpropanolamine, propafenone, propranolol, terbinafine, thiabendazole, ticlopidine, verapamil, zileuton montelukast, moricizine, omeprazole, phenobarbital, phenytoin, cigarette smoking CYP3A4 alprazolam, amiodarone, amlodipine, amprenavir, aprepitant, atorvastatin, atazanavir, bicalutamide, cilostazol, cimetidine, ciprofloxacin, clarithromycin, conivaptan, cyclosporine, darunavir/ritonavir, diltiazem, erythromycin, fluconazole, fluoxetine, fluvoxamine, fosamprenavir, imatinib, indinavir, isoniazid, itraconazole, ketoconazole, lopinavir/ritonavir, nefazodone, nelfinavir, nilotinib, oral contraceptives, posaconazole, ranitidine, ranolazine, ritonavir, saquinavir, telithromycin, tipranavir, voriconazole, zileuton armodafinil, amprenavir, aprepitant, bosentan, carbamazepine, efavirenz, etravirine, modafinil, nafcillin, phenytoin, pioglitazone, prednisone, rifampin, rufinamide Examples of drugs known to increase the risk of bleeding are presented in Table 3.'),
  (40, 145, 'bleeding_risk', 'increase', FALSE, 'Co-administration with anticoagulants, antiplatelets, or NSAIDs can increase risk of bleeding (7.1) Decreased renal function can occur with co-administration with NSAIDs (7.1) Adenosinergic agents (e.g. adenosine, regadenoson)'),
  (40, 563, 'bleeding_risk', 'increase', FALSE, 'Co-administration with anti-coagulants or NSAIDS can increase risk of bleeding (7.4 , 7.10 ) Decreased renal function can occur with co-administration with NSAIDS (7.10) Dipyridamole has been reported to increase the plasma levels and cardiovascular effects of adenosine.'),
  (56, 1490, 'drug_exposure', 'increase', FALSE, 'Praziquantel: In the fed state increased mean maximum plasma concentration and area under the curve of albendazole sulfoxide by about 50% in healthy subjects.'),
  (60, 960, 'hyperglycemia', 'decrease', FALSE, 'The following are examples of substances that may reduce the blood glucose-lowering effect of insulin that may result in hyperglycemia: corticosteroids, danazol, diazoxide, diuretics, sympathomimetic agents (e.g., epinephrine, albuterol, terbutaline), glucagon, isoniazid, phenothiazine derivatives, somatropin, thyroid hormones, estrogens, progestogens (e.g., in oral contraceptives), protease inhibitors, and atypical antipsychotic medications (e.g., olanzapine and clozapine).'),
  (60, 1814, 'drug_exposure', 'unspecified', TRUE, 'albuterol, diltiazem medroxyprogesterone roxithromycin systemic and inhaled dirithromycin methylprednisolone sorbitol amoxicillin enflurane metronidazole (purgative doses ampicillin, famotidine metoprolol do not inhibit with or without felodipine nadolol theophylline sulbactam finasteride nifedipine absorption) atenolol hydrocortisone nizatidine sucralfate azithromycin isoflurane norfloxacin terbutaline, systemic caffeine, isoniazid ofloxacin terfenadine dietary ingestion isradipine omeprazole tetracycline cefaclor influenza vaccine prednisone, tocainide co-trimoxazole ketoconazole prednisolone (trimethoprim and lomefloxacin ranitidine sulfamethoxazole) mebendazole rifabutin The Effect of Other Drugs on Theophylline Serum Concentration Measurements: Most serum theophylline assays in clinical use are immunoassays which are specific for theophylline.'),
  (68, 767, 'drug_exposure', 'increase', FALSE, 'A study observed a reduction in clearance and distribution volume as well as prolongation of T of alfentanil following concomitant treatment with fluconazole.'),
  (68, 767, 'hypoglycemia', 'increase', FALSE, 'Hydrochlorothiazide Alfentanil Amitriptyline, nortriptyline Amphotericin B Azithromycin Carbamazepine Calcium Channel Blockers Celecoxib Cyclophosphamide Fentanyl Halofantrine HMG-CoA reductase inhibitors Losartan Methadone Non-steroidal anti-inflammatory drugs Prednisone Saquinavir Sirolimus Vinca Alkaloids Vitamin A Zidovudine Clinically significant hypoglycemia may be precipitated by the use of fluconazole with oral hypoglycemic agents; one fatality has been reported from hypoglycemia in association with combined fluconazole and glyburide use.'),
  (68, 861, 'drug_exposure', 'decrease', FALSE, '( 7.2 ) CYP3A4 Substrates with narrow therapeutic index (e.g., alfentanil, quinidine, cyclosporine) : RAVICTI may decrease exposure; monitor for decreased efficacy of the narrow therapeutic index drug.'),
  (68, 1006, 'arrhythmia_risk', 'increase', FALSE, 'Alpha Blockers tamsulosin Analgesics methadone alfentanil, buprenorphine IV and sublingual, fentanyl, oxycodone, sufentanil Methadone: The potential increase in plasma concentrations of methadone when coadministered with itraconazole may increase the risk of serious cardiovascular events including QTc prolongation and torsade de pointes .'),
  (68, 1016, 'arrhythmia_risk', 'increase', FALSE, 'Alpha Blockers tamsulosin Analgesics methadone alfentanil, buprenorphine IV and sublingual, fentanyl, oxycodone, sufentanil Methadone: The potential increase in plasma concentrations of methadone when coadministered with ketoconazole tablets may increase the risk of serious cardiovascular events including QT prolongation and torsade de pointes, or respiratory or CNS depression.'),
  (68, 1016, 'cns_depression', 'increase', FALSE, 'Alpha Blockers tamsulosin Analgesics methadone alfentanil, buprenorphine IV and sublingual, fentanyl, oxycodone, sufentanil Methadone: The potential increase in plasma concentrations of methadone when coadministered with ketoconazole tablets may increase the risk of serious cardiovascular events including QT prolongation and torsade de pointes, or respiratory or CNS depression.'),
