  (122, 409, 'bleeding_risk', 'increase', FALSE, 'APPRAISE-2, a placebo-controlled clinical trial of apixaban in high-risk, post-acute coronary syndrome patients treated with aspirin or the combination of aspirin and clopidogrel, was terminated early due to a higher rate of bleeding with apixaban compared to placebo.'),
  (122, 413, 'bleeding_risk', 'increase', FALSE, 'Anticoagulants: Direct Oral Anticoagulants (DOACs) apixaban ↑ apixaban Due to potentially increased bleeding risk, dosing recommendations for co-administration of apixaban with SYMTUZA depend on the apixaban dose.'),
  (122, 477, 'bleeding_risk', 'increase', FALSE, 'Anticoagulants: Direct Oral Anticoagulants (DOACs) apixaban ↑ apixaban Due to potentially increased bleeding risk, dosing recommendations for co-administration of apixaban with darunavir/ritonavir depend on the apixaban dose.'),
