  (416, 1223, 'drug_exposure', 'increase', FALSE, 'The risk of infant exposure to codeine and morphine through breast milk should be weighed against the benefits of breastfeeding for both the mother and baby.'),
  (416, 1223, 'respiratory_depression', 'increase', FALSE, 'Discontinuation of a concomitantly used CYP2D6 inhibitor may result in a decrease in codeine plasma concentration and an increase in active metabolite morphine plasma concentration which could increase or prolong adverse reactions and may cause potentially fatal respiratory depression.'),
