  (1011, 1094, 'qt_prolongation', 'unspecified', TRUE, 'Avoid co-administration of encorafenib or ivosidenib with lopinavir and ritonavir due to potential risk of serious adverse events such as QT interval prolongation.'),
  (1011, 1281, 'qt_prolongation', 'unspecified', TRUE, 'Anticancer drugs abemaciclib, ceritinib, dasatinib, encorafenib, ibrutinib, ivosidenib, neratinib, nilotinib, venetoclax, vinblastine, vincristine ↑ anticancer drugs Avoid co-administration of encorafenib or ivosidenib due to potential risk of serious adverse events such as QT interval prolongation.'),
  (1011, 1589, 'qt_prolongation', 'unspecified', TRUE, 'Avoid co-administration of encorafenib or ivosidenib with ritonavir due to potential risk of serious adverse events such as QT interval prolongation.'),
  (1015, 1069, 'hypertension', 'unspecified', FALSE, 'Concurrent use of ketamine and levothyroxine may produce marked hypertension and tachycardia.'),
